const nexusIconPaths={overview:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',website:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M7 6.5h.1M10 6.5h.1"/>',crm:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-2a6 6 0 0 1 12 0v2M16 5a3 3 0 0 1 0 6M21 20v-2a6 6 0 0 0-4-5"/>',campaigns:'<path d="m3 10 14-5v14L3 14zM6 15l2 6h3l-2-5M21 8v8"/>',agent:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',workflows:'<rect x="8" y="2" width="8" height="6" rx="1"/><rect x="2" y="16" width="7" height="6" rx="1"/><rect x="15" y="16" width="7" height="6" rx="1"/><path d="M12 8v4M5 16v-4h14v4"/>',analytics:'<path d="M4 20V11M10 20V4M16 20v-7M22 20H2"/>',webinars:'<rect x="3" y="5" width="14" height="14" rx="2"/><path d="m17 10 5-3v10l-5-3M8 9l5 3-5 3z"/>',billing:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20M6 15h3"/>',settings:'<path d="m12 3 2 3 4-1 1 4 3 3-3 3-1 4-4-1-2 3-2-3-4 1-1-4-3-3 3-3 1-4 4 1z"/><circle cx="12" cy="12" r="3"/>',projects:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><path d="M3 14h7v7H3zM14 14h7v7h-7z"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',home:'<path d="m3 10 9-7 9 7v10H3zM9 20v-7h6v7"/>',external:'<path d="M14 3h7v7M21 3l-9 9M10 3H3v18h18v-7"/>',shield:'<path d="m12 2 8 4v6c0 5-8 10-8 10S4 17 4 12V6zM8 12l3 3 5-6"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',bell:'<path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 21h4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};
function nxIcon(n,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${nexusIconPaths[n]||nexusIconPaths.overview}</svg>`}
Object.keys(icons).forEach(k=>icons[k]=nxIcon(k));icons.projects=nxIcon('projects');
const nxProjects=[{id:'orbit',name:'Orbit',category:'SaaS',line:'A launch with everything in orbit.',desc:'A product website, a developer community, and a subscription journey that share the same customer story.',color:'blue',tag:'Product launch',domain:'orbit.example',modules:['Website','CRM','Billing'],headline:'Give your next idea\na place to launch.'},{id:'forma',name:'Forma',category:'Agency',line:'Good work deserves a great first impression.',desc:'A considered studio website with project inquiries connected to a clear client pipeline.',color:'green',tag:'Agency workspace',domain:'forma.example',modules:['Website','CRM','Campaigns'],headline:'Independent minds.\nExceptional work.'},{id:'gather',name:'Gather',category:'Education',line:'From a first lesson to a lasting community.',desc:'An expert-led learning experience connecting class registration, attendees, and thoughtful follow-up.',color:'yellow',tag:'Learning & events',domain:'gather.example',modules:['Website','Webinars','Campaigns'],headline:'Your next chapter\nstarts with curiosity.'},{id:'pulse',name:'Pulse',category:'SaaS',line:'A clearer path from trial to subscription.',desc:'A product landing page built around one shared customer view, from first visit to the next renewal.',color:'pink',tag:'Subscription business',domain:'pulse.example',modules:['Website','CRM','Billing'],headline:'Less noise.\nMore momentum.'}];
let nxProjectFilter='All projects',nxStep=0,nxView='grid';
const nxSteps=[{name:'Website',title:'A first impression that goes somewhere.',body:'A visitor discovers your business. A template-based website tells your story and gives them a clear next step.',action:'Explore website concept',page:'website',person:'Visitor',event:'Viewed the product page',context:'Website visit',metric:'1 shared journey',icon:'website'}, {name:'CRM',title:'A person, not another spreadsheet row.',body:'Their inquiry becomes a contact with context. Your team sees where they came from and what caught their attention.',action:'Explore CRM concept',page:'crm',person:'Qualified lead',event:'Requested a product walkthrough',context:'Website CRM',metric:'Customer context',icon:'crm'}, {name:'Campaigns',title:'Keep the conversation moving.',body:'Relevant messages build on what you already know. Audiences and campaign drafts stay connected to customer relationships.',action:'Explore campaign concept',page:'campaigns',person:'Engaged contact',event:'Opened the event invitation',context:'CRM Campaigns',metric:'Relevant follow-up',icon:'campaigns'}, {name:'Webinars',title:'Turn interest into a real connection.',body:'A registration page, reminders, and attendance belong to the same journey. Every conversation adds context for the next.',action:'Explore webinar concept',page:'webinars',person:'Webinar attendee',event:'Attended the product masterclass',context:'Campaigns Webinars',metric:'A richer relationship',icon:'webinars'}, {name:'Billing',title:'Connect the next chapter to revenue.',body:'Subscription views bring the commercial relationship into focus. The customer story continues after the first conversion.',action:'Explore billing concept',page:'billing',person:'Active customer',event:'Selected the Pro subscription',context:'Webinars Billing',metric:'Connected revenue',icon:'billing'}];
function nxBrand(){return '<span class="nx-symbol" aria-hidden="true"><i></i><i></i><i></i></span><span>nexus</span>'}
function nxProductMockup(){return `<div class="nx-product-stage"><div class="nx-stage-label"><span class="nx-status-dot"></span> One workspace. A complete picture.</div><div class="nx-browser"><div class="nx-browser-chrome"><div class="nx-browser-dots"><i></i><i></i><i></i></div><span>${nxIcon('shield',11)} app.nexus.example / acme</span><span>Concept preview</span></div><div class="nx-demo-app"><aside class="nx-demo-sidebar"><div class="nx-demo-brand">${nxBrand()}</div><div class="nx-demo-workspace"><span>A</span> Acme workspace <b>⌄</b></div>${[['overview','Overview'],['projects','Projects'],['website','Websites'],['crm','CRM'],['campaigns','Campaigns'],['agent','AI Agent']].map(([i,n],j)=>`<div class="nx-demo-nav ${j===0?'chosen':''}">${nxIcon(i,12)}${n}</div>`).join('')}<div class="nx-demo-sidebar-foot"><span class="avatar">SM</span> Your workspace</div></aside><div class="nx-demo-main"><div class="nx-demo-topline"><span>Business overview</span><span>October 2026 &nbsp; ⌄</span></div><div class="nx-demo-title"><h3>Good morning, Stevon</h3><p>Here’s where your business is growing.</p></div><div class="nx-demo-stats">${[['Monthly revenue','$24,680','12.8%'],['Active customers','892','8.2%'],['New leads','1,284','18.6%']].map(([n,v,c])=>`<div><small>${n}</small><strong>${v}</strong><span> ${c}</span></div>`).join('')}</div><div class="nx-demo-revenue"><div><h4>Revenue over time</h4><span><i class="nx-status-dot"></i> This month</span></div><svg viewBox="0 0 430 135" role="img" aria-label="Illustrative revenue trend"><path d="M5 20H425M5 60H425M5 100H425" stroke="#eef0f5"/><path d="M5 106C35 112 40 84 67 91S99 109 120 74S159 91 185 68S218 76 245 52S278 67 301 38S335 50 359 28S395 40 425 11V120H5Z" fill="#eef2ff"/><path d="M5 106C35 112 40 84 67 91S99 109 120 74S159 91 185 68S218 76 245 52S278 67 301 38S335 50 359 28S395 40 425 11" fill="none" stroke="#4567db" stroke-width="2.5"/></svg><div class="nx-demo-axis"><span>Oct 1</span><span>Oct 10</span><span>Oct 20</span><span>Oct 31</span></div></div><div class="nx-demo-journey"><strong>Connected customer journey</strong><div>${['Website','Lead','Webinar','Customer'].map((n,i)=>`<span>${i?'<b> </b>':''}${n}</span>`).join('')}</div></div></div></div></div><div class="nx-floating-contact"><span class="nx-person-photo">SC</span><div><strong>Sophia Chen</strong><span>Webinar attendee Customer</span></div><span class="nx-contact-check">${nxIcon('check',13)}</span></div><div class="nx-floating-agent"><span class="nx-agent-glyph">${nxIcon('agent',17)}</span><div><strong>The next move, connected.</strong><span>Attendee follow-up ready for review</span></div><span class="nx-floating-pill">Preview</span></div></div>`}
function nxProjectCover(p){return `<div class="nx-project-art ${p.color}"><div class="nx-project-window"><div class="nx-project-nav"><strong>${p.name.toLowerCase()}${p.id==='forma'?'/':'.'}</strong><span>${p.id==='gather'?'Courses &nbsp; About':'Product &nbsp; Studio'} &nbsp; <i>Get started</i></span></div><div class="nx-project-presentation"><div class="nx-project-heading">${esc(p.headline).replace('\n','<br>')}</div><p>${p.id==='forma'?'Strategy, design, and a little unexpected.':p.id==='gather'?'Learn something that moves you forward.':'Everything you need to make your next move.'}</p><span class="nx-micro-cta">${p.id==='forma'?'Explore our work':p.id==='gather'?'Find your next class':'Meet the platform'}</span></div><div class="nx-art-object ${p.id}">${p.id==='orbit'?'<div class="orbit-ring r1"></div><div class="orbit-ring r2"></div><div class="orbit-ring r3"></div><div class="orbit-core"></div>':p.id==='forma'?'<div class="forma-block b1"></div><div class="forma-block b2"></div><div class="forma-block b3"></div>':p.id==='gather'?'<div class="gather-flower">✳</div><div class="gather-tag">Ideas grow here.</div>':'<div class="pulse-chart"><i></i><i></i><i></i><i></i><i></i></div>'}</div></div><span class="nx-project-concept">Example concept</span></div>`}
function nxProjectCards(filter='All projects',workspace=false){return nxProjects.filter(p=>filter==='All projects'||p.category===filter).map(p=>`<article class="nx-project-card">${nxProjectCover(p)}<div class="nx-project-info"><div><span class="nx-project-type">${p.category}</span><h3>${p.name}<span>${workspace?p.tag:p.line}</span></h3></div><button class="nx-arrow-button" data-project="${p.id}" aria-label="Explore ${p.name} project">${nxIcon('arrow',18)}</button></div><div class="nx-project-modules">${p.modules.map(m=>`<span>${m}</span>`).join('')}<button data-project="${p.id}">View project</button></div></article>`).join('')}
function nxJourneyScene(){const s=nxSteps[nxStep];return `<div class="nx-journey-copy"><span class="nx-small-caption">${String(nxStep+1).padStart(2,'0')} / One continuous journey</span><h3>${s.title}</h3><p>${s.body}</p><button class="nx-text-button" data-page="${s.page}">${s.action} ${nxIcon('arrow',16)}</button></div><div class="nx-journey-visual"><div class="nx-context-label">${nxIcon(s.icon,16)} ${s.context}<span>Concept data</span></div><div class="nx-customer-card"><div class="nx-customer-head"><span class="nx-person-photo large">SC</span><div><h4>Sophia Chen</h4><p>Product lead at Orbit</p></div><span class="nx-customer-state">${s.person}</span></div><div class="nx-customer-event"><span>${nxIcon(s.icon,20)}</span><div><small>Latest touchpoint</small><strong>${s.event}</strong><p>Linked to the same customer record</p></div><i class="nx-status-dot"></i></div><div class="nx-customer-stages">${nxSteps.map((step,i)=>`<div class="${i<=nxStep?'done':''}">${nxIcon(i<nxStep?'check':step.icon,13)}<span>${step.name}</span></div>`).join('')}</div></div><div class="nx-journey-foot">${nxIcon('workflows',16)}<span>${s.metric}</span><span>No context left behind</span></div></div>`}
function renderHome(){document.body.classList.add('marketing-page');document.getElementById('app').innerHTML=`<div class="nx-home"><a class="nx-skip" href="#main-story" data-scroll="main-story">Skip to content</a><header class="nx-header"><div class="nx-container nx-nav-row"><button class="nx-logo" data-page="home" aria-label="Nexus home">${nxBrand()}</button><nav class="nx-main-nav" aria-label="Main navigation"><button data-scroll="connected-story">Platform</button><button data-scroll="projects-showcase">Customer projects</button><button data-scroll="operations-story">How it works</button><button data-scroll="questions">Resources</button></nav><div class="nx-nav-actions"><button class="nx-nav-login" data-page="overview">Explore workspace</button><button class="nx-button small primary" data-page="projects">View projects ${nxIcon('arrow',15)}</button><button class="nx-mobile-nav-toggle" data-home-menu aria-label="Toggle main navigation" aria-expanded="false">${nxIcon('menu')}</button></div></div></header><main id="main-story" tabindex="-1"><section class="nx-hero nx-container"><div class="nx-hero-copy"><span class="nx-announcement"><span class="nx-status-dot"></span>A new perspective on business operations</span><h1>Great businesses<br>grow together.</h1><p>Your website, customers, campaigns, and revenue.<br class="nx-desktop-br"> One connected workspace to bring it all into focus.</p><div class="nx-hero-actions"><button class="nx-button primary" data-page="projects">Explore the workspace ${nxIcon('arrow',17)}</button><button class="nx-button quiet" data-scroll="connected-story"><span class="nx-play">▷</span>See the bigger picture</button></div><div class="nx-hero-note"><span class="nx-avatar-stack"><i>JS</i><i>AL</i><i>MK</i></span><span>Designed for the people<br><strong>building what comes next.</strong></span></div></div>${nxProductMockup()}</section><section class="nx-concept-strip"><div class="nx-container"><p>A workspace for every kind of ambition.</p><div><span>orbit<span class="nx-logo-orbit">◉</span></span><span class="nx-wordmark-forma">forma/</span><span class="nx-wordmark-gather">✳ gather</span><span class="nx-wordmark-pulse">ııı pulse</span><span class="nx-concept-caption">Illustrative project brands</span></div></div></section><section id="connected-story" class="nx-story-section nx-container"><div class="nx-section-heading"><div><span class="nx-section-tag">The connected business</span><h2>Every next step.<br>Part of the same story.</h2></div><p>Growth doesn’t happen in separate tabs. Follow one customer from their first visit to a lasting relationship.</p></div><div class="nx-journey-tabs" role="tablist" aria-label="Customer journey stages">${nxSteps.map((s,i)=>`<button role="tab" id="journey-tab-${i}" aria-controls="journey-panel" aria-selected="${i===nxStep}" tabindex="${i===nxStep?'0':'-1'}" class="${i===nxStep?'current':''}" data-journey="${i}"><span>${nxIcon(s.icon,18)}</span>${s.name}<i>${nxIcon('arrow',14)}</i></button>`).join('')}</div><div class="nx-journey-scene" id="journey-panel" role="tabpanel" aria-labelledby="journey-tab-${nxStep}">${nxJourneyScene()}</div></section><section id="projects-showcase" class="nx-showcase-section"><div class="nx-container"><div class="nx-section-heading"><div><span class="nx-section-tag">Made for your next chapter</span><h2>Different ambitions.<br>One place to build.</h2></div><div><p>A few ways a connected workspace could come to life. Explore our example customer projects.</p><span class="nx-showcase-disclaimer">Design concepts, not customer endorsements.</span></div></div><div class="nx-showcase-toolbar"><div class="nx-filter-tabs" aria-label="Filter project concepts">${['All projects','SaaS','Agency','Education'].map(n=>`<button class="${nxProjectFilter===n?'selected':''}" data-project-filter="${n}" aria-pressed="${nxProjectFilter===n}">${n}</button>`).join('')}</div><button class="nx-text-button" data-page="projects">Open project workspace ${nxIcon('external',14)}</button></div><div class="nx-project-grid" id="showcase-grid">${nxProjectCards(nxProjectFilter)}</div></div></section><section class="nx-product-section nx-container" id="platform-scenes"><div class="nx-section-heading"><div><span class="nx-section-tag">Clarity, across your business</span><h2>Less switching.<br>More moving forward.</h2></div><p>A considered home for your work. Familiar tools with the shared context that makes them better together.</p></div><div class="nx-feature-pair"><article class="nx-feature-panel"><div class="nx-feature-caption">${nxIcon('website')}<h3>A website with a job to do.</h3><p>Start with a template. Make it yours. Connect the next step.</p></div><div class="nx-builder-mock"><aside><strong>Page sections</strong><span>⠿ Navigation</span><span class="active">⠿ Hero section</span><span>⠿ Features</span><span>⠿ Lead form <i>CRM</i></span><span>⠿ Pricing <i>Billing</i></span></aside><div class="nx-builder-preview"><div>orbit. <span>Product &nbsp; About</span></div><h4>Build something<br>worth starting.</h4><p>Bring your next big idea to life.</p><span class="nx-builder-cta">Get started</span><div class="nx-builder-outline"></div></div><div class="nx-builder-floating"><span>Brand color</span><i style="background:var(--nx-brand)"></i><i style="background:var(--nx-ink)"></i><i style="background:var(--nx-brand)"></i>${nxIcon('check',12)}</div></div><button class="nx-feature-link" data-page="builder">Explore the builder ${nxIcon('arrow',17)}</button></article><article class="nx-feature-panel pale"><div class="nx-feature-caption">${nxIcon('crm')}<h3>Know the person behind the pipeline.</h3><p>Every interaction adds to one shared customer view.</p></div><div class="nx-pipeline-mock">${[['New lead','2','Orbit','Sophia Chen','Website inquiry'],['In conversation','3','Forma','James Wilson','Webinar attendee'],['Customer','4','Pulse','Amelia Kim','Pro subscription']].map(([n,c,company,person,source],i)=>`<div class="nx-pipeline-column"><h4><i style="background:${['var(--nx-brand)','var(--nx-brand)','var(--nx-brand)'][i]}"></i>${n}<span>${c}</span></h4><div><span class="nx-pipeline-company">${company[0]}</span><strong>${company}</strong><p>${person}</p><small>${source}</small><footer><span>Shared customer record</span>${nxIcon('crm',12)}</footer></div><div class="nx-pipeline-ghost"></div></div>`).join('')}</div><button class="nx-feature-link" data-page="crm">Explore the CRM ${nxIcon('arrow',17)}</button></article></div></section><section id="operations-story" class="nx-operations"><div class="nx-container nx-operations-grid"><div class="nx-operations-copy"><span class="nx-section-tag light">Your next move, thoughtfully planned</span><h2>A bigger ambition.<br>A clearer plan.</h2><p>Describe the outcome you have in mind. Nexus brings the right parts of your business into the conversation.</p><div class="nx-approval-note">${nxIcon('shield',22)}<div><strong>You stay in control.</strong><p>Review the plan before anything reaches a customer.</p></div></div><button class="nx-button white" data-page="agent">Explore the agent concept ${nxIcon('arrow',17)}</button></div><div class="nx-agent-story"><div class="nx-agent-story-head"><span>${nxIcon('agent',18)} Nexus AI</span><small>Illustrative workflow</small></div><div class="nx-story-prompt">“Plan a product webinar. Build the page, prepare an audience, and show me the campaign before it goes out.”</div><div class="nx-story-response"><span class="nx-agent-response-icon">${nxIcon('agent',19)}</span><div><h3>Let’s connect the pieces.</h3><p>Here’s a proposed plan for your review.</p></div></div><div class="nx-story-plan">${[['webinars','Create the event draft','Product webinar. 45 minutes'],['website','Prepare a registration page','Orbit template. Event registration'],['crm','Build an audience preview','Interested contacts. Shared CRM data'],['campaigns','Draft the invitation','Ready for your review']].map(([ico,n,d],i)=>`<div><span class="nx-plan-check">${i===3?nxIcon('shield',14):nxIcon('check',14)}</span><div><strong>${n}</strong><small>${d}</small></div><span>${nxIcon(ico,17)}</span></div>`).join('')}</div><div class="nx-story-plan-bottom"><span>Approval required</span><button data-action="review">Review campaign ${nxIcon('arrow',14)}</button></div></div></div></section><section id="questions" class="nx-faq-section nx-container"><div><span class="nx-section-tag">A little more context</span><h2>Built around<br>how business works.</h2><p>Start with the blueprint.<br>Imagine what connects next.</p></div><div class="nx-faq-list">${[['What is Nexus?','Nexus is a concept for a connected business operating platform. The intended product brings websites, CRM, campaigns, webinars, subscriptions, analytics, and AI workflows into one shared workspace.'],['Who is this workspace designed for?','Founders, agencies, sales teams, educators, and business operators who want a clearer view of the whole customer journey. The example projects show a few of those directions.'],['How does the website builder work?','The intended builder starts with templates and predefined sections. Brand tokens, content, and business component bindings form a structured page model. This preview illustrates the editing experience.'],['What can I explore in this version?','You can explore the homepage, project concepts, module layouts, product mockups, and temporary UI interactions. Business functionality, integrations, and backend services will be built in a later phase.']].map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div></section><section class="nx-final-cta nx-container"><div class="nx-cta-mark">${nxBrand()}</div><h2>Your whole business.<br>A little more together.</h2><p>Take a look around. Your next chapter starts here.</p><button class="nx-button primary" data-page="projects">Explore the workspace ${nxIcon('arrow',17)}</button><span class="nx-final-note">Frontend concept. Mock data. No setup needed</span></section></main><footer class="nx-footer"><div class="nx-container"><div class="nx-footer-top"><div><button class="nx-logo" data-page="home">${nxBrand()}</button><p>A more connected way to grow.</p></div><div><strong>Platform</strong><button data-page="website">Websites</button><button data-page="crm">CRM</button><button data-page="agent">AI operations</button></div><div><strong>Explore</strong><button data-scroll="projects-showcase">Project concepts</button><button data-page="overview">Workspace</button><button data-page="analytics">Analytics preview</button></div><div><strong>About this concept</strong><p>Designed as a frontend blueprint.<br>Business features are coming later.</p><span class="nx-footer-preview">Design preview</span></div></div><div class="nx-footer-bottom"><span>© 2026 Nexus. A business platform concept.</span><span>One workspace. Every next step.</span><button data-scroll="main-story">Back to top ↑</button></div></div></footer></div>`;}
